package dev.veltraph.client.combat.ghost;
import dev.veltraph.client.combat.ghost.GhostSourcePathSmoothing.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class GhostSourcePathSmoothingTest {
 static Cell p(int x,int y,int z){return new Cell(x,y,z);}
 static class World implements GhostSourcePathSmoothing.World {
  final List<Cell> visits=new ArrayList<>();final Set<Cell> blocked=new HashSet<>(),opaque=new HashSet<>();
  public Boolean loaded(Cell p){return true;}public Boolean passable(Cell p){return !opaque.contains(p);}public Boolean blocked(Cell p){visits.add(p);return blocked.contains(p);}
  public Double supportRelative(Cell p){return 1d;}public Double supportAbsolute(Cell p){return p.y()+1d;}
  public Stair stair(Cell p){return new Stair(false,null);}public Boolean cocoa(Cell p){return false;}public Boolean support(Cell p,boolean volume){return true;}
  public Boolean foot(Cell p){return p.y()==0;}public Boolean headClearOne(Cell p){return true;}
 }
 static Context ordinary(Known gate,Known present,Known bypass,Known veto,int strength){return new Context(gate,false,false,present,bypass,veto,strength);}
 @Test void disabledOriginalToggleSkipsEveryObservationAndUnknownNeverPublishes(){var path=List.of(p(0,0,0),p(1,0,0));var w=new World(){public Double supportRelative(Cell p){throw new AssertionError();}};assertEquals(path,GhostSourcePathSmoothing.apply(path,ordinary(Known.NO,Known.UNKNOWN,Known.UNKNOWN,Known.UNKNOWN,1),w).cells());assertThrows(MissingObservation.class,()->GhostSourcePathSmoothing.apply(path,ordinary(Known.UNKNOWN,Known.NO,Known.NO,Known.NO,1),w));}
 @Test void ordinaryOrderAndVolumeOrderAreDistinct(){var path=List.of(p(0,0,0),p(1,0,0),p(2,0,0));assertEquals(List.of("A","B","D","F","G"),GhostSourcePathSmoothing.apply(path,ordinary(Known.YES,Known.NO,Known.UNKNOWN,Known.UNKNOWN,0),new World()).transforms());assertEquals(List.of("A","B","C","D","E"),GhostSourcePathSmoothing.apply(path,new Context(Known.YES,false,true,Known.NO,Known.UNKNOWN,Known.UNKNOWN,null),new World()).transforms());}
 @Test void parentBypassReturnsAfterInitialStagesAndTailVetoOnlySkipsG(){var path=List.of(p(0,0,0),p(1,0,0),p(2,0,0));assertEquals(List.of("A","B"),GhostSourcePathSmoothing.apply(path,ordinary(Known.YES,Known.YES,Known.YES,Known.UNKNOWN,1),new World()).transforms());assertEquals(List.of("A","B","D","F"),GhostSourcePathSmoothing.apply(path,ordinary(Known.YES,Known.YES,Known.NO,Known.YES,1),new World()).transforms());assertThrows(MissingObservation.class,()->GhostSourcePathSmoothing.apply(path,ordinary(Known.YES,Known.YES,Known.UNKNOWN,Known.NO,1),new World()));}
 @Test void aRemovesUniformTriplesButKeepsUnequalSpacing(){var w=new World();assertEquals(List.of(p(0,0,0),p(2,0,0)),GhostSourcePathSmoothing.a(List.of(p(0,0,0),p(1,0,0),p(2,0,0)),w));var uneven=List.of(p(0,0,0),p(1,0,0),p(3,0,0));assertEquals(uneven,GhostSourcePathSmoothing.a(uneven,w));}
 @Test void aDuplicateLegRequiresEqualYAndExactSupportHeight(){var path=List.of(p(0,0,0),p(0,0,0),p(1,0,0));assertEquals(List.of(path.getFirst(),path.getLast()),GhostSourcePathSmoothing.a(path,new World()));var changing=new World(){public Double supportRelative(Cell p){return p.x()==1?1.000001:1d;}};assertEquals(path,GhostSourcePathSmoothing.a(path,changing));var vertical=List.of(p(0,0,0),p(0,1,0),p(1,1,0));assertEquals(vertical,GhostSourcePathSmoothing.a(vertical,new World()));}
 @Test void aReadsAllThreeSupportObservationsBeforeComparing(){var w=new World(){public Double supportRelative(Cell p){if(p.x()==2)return null;return p.x()==1?2d:1d;}};assertThrows(MissingObservation.class,()->GhostSourcePathSmoothing.a(List.of(p(0,0,0),p(1,0,0),p(2,0,0)),w));}
 @Test void bOnlyDropsAnAxisAlignedSameFacingOneStepStair(){var path=List.of(p(0,0,0),p(1,1,0),p(2,2,0));var same=new World(){public Stair stair(Cell p){return new Stair(true,"east");}};assertEquals(List.of(path.getFirst(),path.getLast()),GhostSourcePathSmoothing.b(path,same));assertEquals(path,GhostSourcePathSmoothing.b(path,new World()));var opposite=new World(){public Stair stair(Cell p){return new Stair(true,p.x()==1?"west":"east");}};assertEquals(path,GhostSourcePathSmoothing.b(path,opposite));var diagonal=List.of(p(0,0,0),p(1,1,1),p(2,2,2));assertEquals(diagonal,GhostSourcePathSmoothing.b(diagonal,same));}
 @Test void bKeepsFullyVerticalAndFlatTriples(){var w=new World(){public Stair stair(Cell p){return new Stair(true,"north");}};var vertical=List.of(p(0,0,0),p(0,1,0),p(0,2,0));assertEquals(vertical,GhostSourcePathSmoothing.b(vertical,w));var flat=List.of(p(0,0,0),p(1,0,0),p(2,0,0));assertEquals(flat,GhostSourcePathSmoothing.b(flat,w));}
 @Test void cOnlyDropsSameXZTripleWithThreeActualCocoaBlocks(){var vertical=List.of(p(1,0,1),p(1,1,1),p(1,2,1));var cocoa=new World(){public Boolean cocoa(Cell p){return true;}};assertEquals(List.of(vertical.getFirst(),vertical.getLast()),GhostSourcePathSmoothing.c(vertical,cocoa));assertEquals(vertical,GhostSourcePathSmoothing.c(vertical,new World()));var bend=List.of(p(1,0,1),p(2,1,1),p(1,2,1));assertEquals(bend,GhostSourcePathSmoothing.c(bend,cocoa));}
 @Test void dAndePreserveLaggedFailureDuplicateInsteadOfGuessingNextNode(){var path=List.of(p(0,0,0),p(1,1,0));assertEquals(List.of(path.getFirst(),path.getFirst(),path.getLast()),GhostSourcePathSmoothing.d(path,new World(),false));var blocked=new World(){public Boolean passable(Cell p){return false;}};assertEquals(List.of(path.getFirst(),path.getFirst(),path.getLast()),GhostSourcePathSmoothing.e(path,blocked));}
 @Test void dChecksAllNineOffsetsAndRejectsLowSupportButHighRayBypassesSupport(){var calls=new ArrayList<Cell>();var w=new World(){public Boolean support(Cell p,boolean volume){calls.add(p);return true;}};assertTrue(GhostSourcePathSmoothing.dEdge(p(0,0,0),p(1,0,0),w,false));assertTrue(calls.stream().anyMatch(p->p.x()==-1&&p.z()==-1));assertTrue(calls.stream().anyMatch(p->p.x()==0&&p.z()==0));assertFalse(calls.stream().anyMatch(p->p.y()>0));var noSupport=new World(){public Boolean support(Cell p,boolean volume){return false;}};assertFalse(GhostSourcePathSmoothing.dEdge(p(0,0,0),p(1,0,0),noSupport,false));}
 @Test void dUsesFloorForNegativeCoordinatesAndExcludesExactTargetEndpoint(){var w=new World();w.opaque.add(p(2,0,0));assertTrue(GhostSourcePathSmoothing.dEdge(p(0,0,0),p(2,0,0),w,false));assertTrue(w.visits.contains(p(-1,0,-1)));assertFalse(w.visits.contains(p(2,0,0)));}
 @Test void dHasHazardVetoWhereEUsesOnlyLoadedPassableAndSupport(){var w=new World();w.blocked.add(p(0,0,0));assertFalse(GhostSourcePathSmoothing.dEdge(p(0,0,0),p(1,0,0),w,false));assertTrue(GhostSourcePathSmoothing.eEdge(p(0,0,0),p(1,0,0),w));}
 @Test void fPreservesEveryAbsoluteHeightJumpAndDuplicateEndpoints(){var path=List.of(p(0,0,0),p(1,1,0),p(2,2,0));assertEquals(List.of(path.get(0),path.get(0),path.get(1),path.get(1),path.get(2),path.get(2)),GhostSourcePathSmoothing.f(path,new World()));assertEquals(List.of(p(0,0,0),p(0,0,0)),GhostSourcePathSmoothing.f(List.of(p(0,0,0)),new World()));}
 @Test void fBlockedLowerCandidateRejectsImmediatelyBeforeAvailableLevelCandidate(){var w=new World();w.blocked.add(p(0,-1,0));var path=List.of(p(0,0,0),p(1,0,0));assertEquals(List.of(path.getFirst(),path.getFirst(),path.getLast()),GhostSourcePathSmoothing.f(path,w));assertEquals(List.of(p(0,-1,0)),w.visits);}
 @Test void fRequiresOneHeadClearanceAfterFirstEligibleCandidate(){var w=new World(){public Boolean headClearOne(Cell p){return false;}};var path=List.of(p(0,0,0),p(1,0,0));assertEquals(List.of(path.getFirst(),path.getFirst(),path.getLast()),GhostSourcePathSmoothing.f(path,w));}
 @Test void gStrengthZeroReturnsInputAndStartsAtIndexOne(){var path=List.of(p(0,0,0),p(1,0,0));var w=new World(){public Double supportAbsolute(Cell p){throw new AssertionError("Two-node G must not enter loop");}};assertSame(path,GhostSourcePathSmoothing.g(path,w,0));assertEquals(path,GhostSourcePathSmoothing.g(path,w,1));}
 @Test void gUsesFullEuclideanDistanceAndStrictGreaterThanStrength(){var path=List.of(p(0,0,0),p(1,0,0),p(2,0,0));assertEquals(List.of(path.getFirst(),path.getLast()),GhostSourcePathSmoothing.g(path,new World(),2));assertEquals(path,GhostSourcePathSmoothing.g(path,new World(),1));}
 @Test void gAscentGuardIsStrictlyGreaterOneAndDescendingIsNotAbsolute(){var rise=List.of(p(0,0,0),p(1,0,0),p(2,2,0));assertEquals(List.of(rise.getFirst(),rise.get(1),rise.getLast(),rise.getLast()),GhostSourcePathSmoothing.g(rise,new World(),10));var fall=List.of(p(0,2,0),p(1,2,0),p(2,0,0));var permissive=new World(){public Boolean foot(Cell p){return true;}};assertEquals(List.of(fall.getFirst(),fall.getLast()),GhostSourcePathSmoothing.g(fall,permissive,10));}
 @Test void gChecksStandingCenterAndFourCornerRays(){var w=new World();assertTrue(GhostSourcePathSmoothing.gEdge(p(0,0,0),p(2,0,1),w));assertTrue(w.visits.stream().anyMatch(p->p.x()==0&&p.z()==1));assertTrue(w.visits.stream().anyMatch(p->p.x()==1&&p.z()==0));}
 @Test void missingGeometryCannotReturnRawOrPartiallySmoothedPath(){var path=List.of(p(0,0,0),p(1,0,0),p(2,0,0));var w=new World(){public Double supportRelative(Cell p){return null;}};assertThrows(MissingObservation.class,()->GhostSourcePathSmoothing.apply(path,ordinary(Known.YES,Known.NO,Known.NO,Known.NO,1),w));}
}
